// This block runs once per generation, after every SUV has stopped.
each generation {
  // Move up a level once a fifth of the best brains' trips arrive safely.
  autoLevel(share: 20%)
  // Every brain drives two trips, and its fitness adds them up.
  routesPerGeneration(count: 2)
  // Every other generation drives a new city made from a seed.
  if generation % 2 == 1 {
    randomCity(seed: generation)
  }
  if generation % 2 == 0 {
    useCity(id: "midtown")
  }
}
